mapper.select:
SELECT id, user_id, device_id, measure_time, glucose, meal_state FROM t_blood_glucose  AND id = #{id}
 AND user_id = #{userId}
 AND device_id = #{deviceId}
 AND measure_time = #{measureTime}
 AND glucose = #{glucose}
 AND meal_state LIKE CONCAT('%', #{mealState}, '%') ORDER BY id DESC
